const readKeywords = function readKeywords({ text }) {
  let parsed;
  try { parsed = JSON.parse(text); } catch { throw new Error('The model did not return keyword JSON.'); }
  if (!Array.isArray(parsed?.answer) || parsed.answer.length < 15 || parsed.answer.length > 20 || parsed.answer.some((keyword) => typeof keyword !== 'string' || !keyword.trim())) throw new Error('Expected 15–20 nonempty seed keywords in answer.');
  return { keywords: parsed.answer.map((keyword) => keyword.trim().toLowerCase()) };
}

return $input.all().map((item,index)=>({json:readKeywords({text:item.json.text}),pairedItem:{item:index}}));

const prepare = function prepareProfile(inputs) {
  const profile = {};
  for (const name of ['product', 'pain_points', 'goals', 'current_solutions', 'expertise_level']) {
    if (typeof inputs[name] !== 'string' || !inputs[name].trim()) throw new Error('Provide the ideal customer profile field: ' + name);
    profile[name] = inputs[name].trim();
  }
  return { icp: JSON.stringify(profile, null, 2) };
}

return $input.all().map((item,index)=>({json:prepare(item.json),pairedItem:{item:index}}));
